const cfg = $item(0).$node['Config'].json || {};
const rows = $items('Fetch Intro Sent Candidates').map((i) => i.json || {});

const locationId = String(cfg.locationId || '').trim();
const rawApiBaseUrl = String(cfg.ghlApiBaseUrl || 'https://services.leadconnectorhq.com');
const apiBaseUrl = rawApiBaseUrl.endsWith('/') ? rawApiBaseUrl.slice(0, -1) : rawApiBaseUrl;
const apiKey = String(cfg.ghlApiKey || '').trim();
const dryRun = !!cfg.defaultDryRun;

const dispatchTimezone = String(cfg.dispatchTimezone || 'America/New_York').trim() || 'America/New_York';
const dispatchStartHour = Number(cfg.dispatchStartHour ?? 9);
const dispatchEndHour = Number(cfg.dispatchEndHour ?? 19);

function currentHourInTz(tz) {
  const fmt = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', hour12: false });
  return Number(fmt.format(new Date()));
}

const currentHour = currentHourInTz(dispatchTimezone);
const dispatchAllowedWeekdaysRaw = String(cfg.dispatchAllowedWeekdays || '1,2,3,4,5,6');
const dispatchAllowedWeekdays = new Set(
  dispatchAllowedWeekdaysRaw
    .split(',')
    .map((v) => Number(String(v).trim()))
    .filter((n) => Number.isInteger(n) && n >= 0 && n <= 6)
);
const currentWeekday = Number(
  new Intl.DateTimeFormat('en-US', { timeZone: dispatchTimezone, weekday: 'short' })
    .format(new Date())
    .replace('Sun','0').replace('Mon','1').replace('Tue','2').replace('Wed','3').replace('Thu','4').replace('Fri','5').replace('Sat','6')
);
const inAllowedWeekday = dispatchAllowedWeekdays.has(currentWeekday);

const inDispatchWindow = currentHour >= dispatchStartHour && currentHour < dispatchEndHour;

if (!dryRun && (!inDispatchWindow || !inAllowedWeekday)) {
  return [{
    json: {
      summary: {
        ok: true,
        dryRun,
        skippedOutsideWindow: true,
        dispatchTimezone,
        dispatchStartHour,
        dispatchEndHour,
        currentHour,
        currentWeekday,
        allowedWeekdays: Array.from(dispatchAllowedWeekdays).sort(),
        rowsFromQuery: rows.length,
        uniqueCandidates: 0,
        planned: 0,
        queued: 0,
        skippedNotIntroSent: 0,
        skippedMissingEmail: 0,
        skippedEmailDnd: 0,
        skippedDoNotNurture: 0,
        skippedNoBucketTag: 0,
        skippedMultiBucketConflict: 0,
        alreadyP2Enrolled: 0,
        alreadyP2Completed: 0,
        unresolved: 0,
        errors: 0
      },
      sample: []
    }
  }];
}


if (!locationId) throw new Error('Missing Config.locationId');
if (!dryRun && !apiKey) throw new Error('Missing Config.ghlApiKey for live mode');

const eligibleTag = String(cfg.eligibleTag || '').trim().toLowerCase();
const doNotNurtureTag = String(cfg.doNotNurtureTag || '').trim().toLowerCase();

const inProgressTagSet = new Set([
  cfg.p2InProgressTag,
  cfg.p2InProgressTagExecutivesMso,
  cfg.p2InProgressTagExecutivesSso,
  cfg.p2InProgressTagMarketingMso,
  cfg.p2InProgressTagMarketingSso
].map((t) => String(t || '').trim().toLowerCase()).filter(Boolean));

const completedTagSet = new Set([
  cfg.p2CompletedTag,
  cfg.p2CompletedTagExecutivesMso,
  cfg.p2CompletedTagExecutivesSso,
  cfg.p2CompletedTagMarketingMso,
  cfg.p2CompletedTagMarketingSso
].map((t) => String(t || '').trim().toLowerCase()).filter(Boolean));

const bucketTagToQueueTag = new Map([
  [String(cfg.bucketTagExecutivesMso || '').trim().toLowerCase(), String(cfg.queueTagExecutivesMsoP2 || '').trim()],
  [String(cfg.bucketTagExecutivesSso || '').trim().toLowerCase(), String(cfg.queueTagExecutivesSsoP2 || '').trim()],
  [String(cfg.bucketTagMarketingMso || '').trim().toLowerCase(), String(cfg.queueTagMarketingMsoP2 || '').trim()],
  [String(cfg.bucketTagMarketingSso || '').trim().toLowerCase(), String(cfg.queueTagMarketingSsoP2 || '').trim()]
]);

function clean(v) { return String(v ?? '').trim(); }

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

const headers = {
  Authorization: 'Bearer ' + apiKey,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json'
};

async function apiRequest({ method, path, body }) {
  const options = { method, url: apiBaseUrl + path, headers, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || 500,
      data: err?.response?.body || err?.message || err
    };
  }
}

async function resolveContactId(candidate) {
  const fromId = clean(candidate.ghl_contact_id);
  if (fromId) return { ok: true, contactId: fromId, resolvedVia: 'release_log_id' };

  const email = clean(candidate.contact_email).toLowerCase();
  if (!email) return { ok: false, reason: 'missing_id_and_email' };

  const dup = await apiRequest.call(this, {
    method: 'GET',
    path: '/contacts/search/duplicate?locationId=' + encodeURIComponent(locationId) + '&email=' + encodeURIComponent(email)
  });
  if (!dup.ok) return { ok: false, reason: 'duplicate_lookup_failed', details: dup.data };

  const id = clean(dup.data?.contact?.id || dup.data?.id || dup.data?.contactId || '');
  if (!id) return { ok: false, reason: 'email_lookup_no_match' };
  return { ok: true, contactId: id, resolvedVia: 'email_duplicate_lookup' };
}

const dedupe = new Map();
for (const row of rows) {
  const key = clean(row.ghl_contact_id) || clean(row.contact_email).toLowerCase();
  if (!key) continue;
  if (!dedupe.has(key)) dedupe.set(key, row);
}
const candidates = Array.from(dedupe.values());

const runId = new Date().toISOString() + '__emerald_p2_dispatcher';
const results = [];

for (const candidate of candidates) {
  const resolved = dryRun
    ? { ok: true, contactId: clean(candidate.ghl_contact_id) || null, resolvedVia: clean(candidate.ghl_contact_id) ? 'release_log_id' : 'dryrun_email_only' }
    : await resolveContactId.call(this, candidate);

  if (!resolved.ok || !resolved.contactId) {
    results.push({ status: 'skipped_unresolved', reason: resolved.reason || 'unresolved', contact_email: candidate.contact_email || null, details: resolved.details || null });
    continue;
  }

  const contactId = String(resolved.contactId);
  const contactRes = await apiRequest.call(this, { method: 'GET', path: '/contacts/' + encodeURIComponent(contactId) });

  if (!contactRes.ok) {
    results.push({ status: 'error_contact_read', contactId, details: contactRes.data });
    continue;
  }

  const contactData = contactRes.data?.contact || contactRes.data || {};
  const tagList = Array.isArray(contactData.tags) ? contactData.tags : [];
  const tagSet = new Set(tagList.map((t) => clean(t).toLowerCase()).filter(Boolean));

  const email = clean(contactData.email || candidate.contact_email).toLowerCase();
  const hasEmail = !!email;
  const dnd = !!contactData.dnd;
  const dndEmailStatus = String(contactData.dndSettings?.Email?.status || '').toLowerCase();
  const emailBlocked = dnd || dndEmailStatus === 'active' || dndEmailStatus === 'permanent';

  if (!tagSet.has(eligibleTag)) { results.push({ status: 'skipped_not_intro_sent', contactId, email }); continue; }
  if (!hasEmail) { results.push({ status: 'skipped_missing_email', contactId }); continue; }
  if (emailBlocked) { results.push({ status: 'skipped_email_dnd', contactId, email }); continue; }
  if (tagSet.has(doNotNurtureTag)) { results.push({ status: 'skipped_do_not_nurture', contactId, email }); continue; }

  if ([...inProgressTagSet].some((t) => tagSet.has(t))) {
    results.push({ status: 'skipped_already_p2_enrolled', contactId, email });
    continue;
  }
  if ([...completedTagSet].some((t) => tagSet.has(t))) {
    results.push({ status: 'skipped_already_p2_completed', contactId, email });
    continue;
  }

  const matchedBucketQueueTags = [];
  for (const [bucketTag, queueTag] of bucketTagToQueueTag.entries()) {
    if (bucketTag && queueTag && tagSet.has(bucketTag)) matchedBucketQueueTags.push(queueTag);
  }

  if (matchedBucketQueueTags.length === 0) { results.push({ status: 'skipped_no_bucket_tag', contactId, email }); continue; }
  if (matchedBucketQueueTags.length > 1) { results.push({ status: 'skipped_multi_bucket_conflict', contactId, email, queueTags: matchedBucketQueueTags }); continue; }

  const queueTag = matchedBucketQueueTags[0];

  if (dryRun) {
    results.push({ status: 'planned', contactId, email, queueTag, runId });
    continue;
  }

  const tagRes = await apiRequest.call(this, {
    method: 'POST',
    path: '/contacts/' + encodeURIComponent(contactId) + '/tags',
    body: { tags: [queueTag] }
  });

  if (!tagRes.ok) {
    results.push({ status: 'error_add_queue_tag', contactId, email, queueTag, details: tagRes.data });
    continue;
  }

  results.push({ status: 'queued', contactId, email, queueTag, runId });
}

const summary = {
  ok: true,
  dryRun,
  runId,
  rowsFromQuery: rows.length,
  uniqueCandidates: candidates.length,
  planned: results.filter((r) => r.status === 'planned').length,
  queued: results.filter((r) => r.status === 'queued').length,
  skippedNotIntroSent: results.filter((r) => r.status === 'skipped_not_intro_sent').length,
  skippedMissingEmail: results.filter((r) => r.status === 'skipped_missing_email').length,
  skippedEmailDnd: results.filter((r) => r.status === 'skipped_email_dnd').length,
  skippedDoNotNurture: results.filter((r) => r.status === 'skipped_do_not_nurture').length,
  skippedNoBucketTag: results.filter((r) => r.status === 'skipped_no_bucket_tag').length,
  skippedMultiBucketConflict: results.filter((r) => r.status === 'skipped_multi_bucket_conflict').length,
  alreadyP2Enrolled: results.filter((r) => r.status === 'skipped_already_p2_enrolled').length,
  alreadyP2Completed: results.filter((r) => r.status === 'skipped_already_p2_completed').length,
  unresolved: results.filter((r) => r.status === 'skipped_unresolved').length,
  errors: results.filter((r) => String(r.status || '').startsWith('error_')).length
};

return [{ json: { summary, sample: results.slice(0, 250) } }];

